// Mirrors hub/sidebars.js exactly. `companies` and `deals` (fetched from
// Firestore server-side and passed down) fill the auto-generated Watchlist /
// Deal Pipeline / Qualified Deals / Radar / Invested / Deal Screening
// subcategories the way Docusaurus's `{ type: 'autogenerated', dirName: ... }`
// used to -- each company's `stage` field decides which of the five stage
// buckets it lands in. Radar and Invested are real stages (STAGES in
// lib/stages.js), not derived filters: Attio tags a deal Radar/Invested
// directly, and deal_intelligence/config.py's ATTIO_STAGE_MAP forwards that
// onto the matching bucket when the data pipelines run -- so they fill in on
// their own, the same way Watchlist/Pipeline/Qualified already do.
//
// There's no "New Deals" tab here -- 'new' is an internal-only holding stage
// for companies the bulk Attio import couldn't map to a real stage (see
// lib/stages.js's STAGES comment). Those surface on /docs/admin's "Needs
// Triage" table, reachable by direct URL only -- see the Admin note below.
//
// The five stage lists live nested one level down, inside a single non-flat
// "Deals" category -- clicking "Deals" itself just toggles the dropdown open
// (DocsShell renders a category with no `href` as a button, not a link),
// matching Oscar's ask for one Deals tab with a dropdown instead of five
// separate top-level tabs.
//
// Three tabs were dropped from this tree on 2026-07-28 (Oscar: "admin, top
// deals, docs tabs eliminate") -- 'docs' (the Deal Screening / Investment
// Memo dropdown), 'hot-deals' ("Top Deals"), and 'admin'. Their pages
// (/docs/deals, /docs/investment-memos, /docs/hot-deals, /docs/admin) still
// exist and still work -- only the nav entries pointing at them are gone, so
// anyone who needs one still reaches it by direct URL/bookmark.
//
// Each stage/doc-type entry is still marked `flat: true`: it carries its full
// `items` list (needed so breadcrumbs/prev-next still resolve correctly on a
// detail page, and so the sidebar rail still highlights while browsing one),
// but DocsShell renders it as a single non-expanding link straight to the
// tab's page instead of a second chevron-toggled dropdown -- those lists
// grow with every company/doc added and would otherwise dump a long,
// ever-changing name list into the sidebar. Research/Projects keep the
// expand behavior since their item counts are small and fixed.
//
// Every top-level node carries a stable `id`, independent of its (now
// user-editable) label -- applyUserPrefs below keys reorder/rename
// customization off this, never off the label text itself, so renaming a
// tab doesn't orphan its saved position and vice versa.
export function getSidebarTree(companies = [], deals = []) {
  return [
    // Label changed to 'Dashboard' (2026-08-06) to match the Navbar's own
    // "Dashboard" link and what this page now leads with (DealStatsDashboard)
    // -- `id` stays 'capabilities' so a saved tab-order/rename user pref
    // (applyUserPrefs below) doesn't orphan.
    { id: 'capabilities', type: 'doc', href: '/docs/overview', label: 'Dashboard' },
    {
      id: 'deals',
      type: 'category',
      label: 'Deals',
      collapsed: true,
      items: [
        {
          type: 'category',
          label: 'Watchlist',
          flat: true,
          href: '/docs/watchlist',
          items: companies.filter((c) => c.stage === 'watchlist').map((c) => ({ type: 'doc', href: `/docs/watchlist/${c.slug}`, label: c.name })),
        },
        {
          type: 'category',
          label: 'Deal Pipeline',
          flat: true,
          href: '/docs/pipeline',
          items: companies.filter((c) => c.stage === 'pipeline').map((c) => ({ type: 'doc', href: `/docs/pipeline/${c.slug}`, label: c.name })),
        },
        {
          type: 'category',
          label: 'Qualified Deals',
          flat: true,
          href: '/docs/qualified-deals',
          items: companies.filter((c) => c.stage === 'qualified').map((c) => ({ type: 'doc', href: `/docs/qualified-deals/${c.slug}`, label: c.name })),
        },
        {
          type: 'category',
          label: 'Radar',
          flat: true,
          href: '/docs/radar',
          // Matches docs/radar/page.jsx's own filter -- additive `radar` tag
          // included, not just stage === 'radar' -- else a company that only
          // reached Radar via the tag (e.g. still sitting in Pipeline as its
          // real stage while ALSO being watched for its next round) shows on
          // the Radar page's table but never in the sidebar's own item list.
          items: companies.filter((c) => c.stage === 'radar' || c.tags?.includes('radar')).map((c) => ({ type: 'doc', href: `/docs/radar/${c.slug}`, label: c.name })),
        },
        {
          type: 'category',
          label: 'Invested',
          flat: true,
          href: '/docs/invested',
          items: companies.filter((c) => c.stage === 'invested').map((c) => ({ type: 'doc', href: `/docs/invested/${c.slug}`, label: c.name })),
        },
        {
          type: 'category',
          label: 'Passed',
          flat: true,
          href: '/docs/passed',
          // Additive, same reasoning as Radar's own filter above: 'passed'
          // is a tag stamped on top of whatever a company's real stage is
          // (deal_intelligence/import_attio_deals_csv.py is the only writer
          // today), not a stage that replaces it -- a company can carry both
          // its working stage AND this tag at once. Named to match Attio's
          // own "Deal stage" value exactly (Oscar, 2026-08-05).
          items: companies.filter((c) => c.stage === 'passed' || c.tags?.includes('passed')).map((c) => ({ type: 'doc', href: `/docs/passed/${c.slug}`, label: c.name })),
        },
        // Not a stage -- a cross-cutting view over every company already in
        // one of the five stage buckets above, filtered to Attio's own
        // "Top 10 VC" Deals-object view (company.top10VC, see
        // docs/top10-vc/page.jsx and deal_intelligence/firestore_push.py's
        // backfill_top10_vc). `type: 'doc'` (not 'category'): it has no
        // company sub-pages of its own, just links out to each company's
        // real stage page.
        { type: 'doc', href: '/docs/top10-vc', label: 'Top 10 VCs' },
      ],
    },
    { id: 'vcs', type: 'doc', href: '/docs/vcs', label: 'VCs' },
    // Fund I One-Pager lives in the top Navbar now, not here -- see
    // components/Navbar.jsx.
    {
      id: 'research',
      type: 'category',
      label: 'Research',
      collapsed: true,
      href: '/docs/research',
      items: [
        { type: 'doc', href: '/docs/research/market-map', label: 'Market Map Directory' },
      ],
    },
    { id: 'research-chat', type: 'doc', href: '/docs/research-chat', label: 'Research Chat' },
    {
      id: 'projects',
      type: 'category',
      label: 'Projects',
      collapsed: true,
      items: [
        { type: 'doc', href: '/docs/projects/pitchbook-attio', label: 'PitchBook → Attio Pipeline' },
        { type: 'doc', href: '/docs/projects/apollo-reach-out', label: 'Apollo Reach Out' },
        { type: 'doc', href: '/docs/projects/intelligence', label: 'Deal Intelligence' },
        { type: 'doc', href: '/docs/projects/investment-memo', label: 'Investment Memo Generator' },
        { type: 'doc', href: '/docs/projects/hub-docs', label: 'Documentation System' },
      ],
    },
  ];
}

// Applies a user's saved tab customization (see lib/userPrefs.js) to the
// top-level tree only -- nested items (Watchlist/Pipeline/... inside Deals)
// aren't independently reorderable/renamable, just the top-level tabs
// themselves. Renaming never touches `id`, so a renamed tab keeps its saved
// position, and reordering never touches `label`, so a moved tab keeps its
// custom name -- the two customizations are independent by construction.
export function applyUserPrefs(tree, prefs) {
  const { tabOrder = [], labels = {} } = prefs || {};
  const relabeled = tree.map((node) => (node.id && labels[node.id] ? { ...node, label: labels[node.id] } : node));
  if (!tabOrder.length) return relabeled;
  const byId = new Map(relabeled.filter((n) => n.id).map((n) => [n.id, n]));
  const ordered = tabOrder.map((id) => byId.get(id)).filter(Boolean);
  const orderedIds = new Set(ordered.map((n) => n.id));
  const rest = relabeled.filter((n) => !n.id || !orderedIds.has(n.id));
  return [...ordered, ...rest];
}

// Walks the tree and returns the [{ label, href }] trail leading to `pathname`
// (excluding the tree root), the way Docusaurus's default breadcrumbs do.
export function getBreadcrumbs(pathname, tree) {
  function search(nodes, trail) {
    for (const node of nodes) {
      const nextTrail = [...trail, { label: node.label, href: node.href }];
      if (node.href === pathname) return nextTrail;
      if (node.items) {
        const found = search(node.items, nextTrail);
        if (found) return found;
      }
    }
    return null;
  }
  return search(tree, []) || [];
}

// True if `pathname` is this node or a descendant of it — used to
// auto-expand the "Companies" subcategory when viewing a company page.
export function containsPath(node, pathname) {
  if (node.href === pathname) return true;
  if (!node.items) return false;
  return node.items.some((child) => containsPath(child, pathname));
}

// Flattens the tree into linear Previous/Next order — depth-first,
// including a category's own link (e.g. "Research") at the point it's
// encountered. Deliberately does NOT descend into a `flat: true` node's
// `items` (2026-07-29, Oscar: "should take to next or previous section, not
// ... the previous or next company") — those items are per-company detail
// pages (Watchlist/Pipeline/Qualified Deals/Radar/Invested), not
// sub-sections, so Previous/Next from inside one now always lands on the
// neighboring SECTION link (the next stage, Top 10 VCs, VCs, Research, ...)
// instead of alphabetically walking every company in between.
export function flattenDocs(tree) {
  const out = [];
  function walk(nodes) {
    for (const node of nodes) {
      if (node.href) out.push({ href: node.href, label: node.label });
      if (node.items && !node.flat) walk(node.items);
    }
  }
  walk(tree);
  return out;
}

export function getPrevNext(pathname, tree) {
  const flat = flattenDocs(tree);
  const i = flat.findIndex((d) => d.href === pathname);
  if (i === -1) return { prev: null, next: null };
  return { prev: flat[i - 1] || null, next: flat[i + 1] || null };
}
